      return;
    }

    const stories: any[] = content.userStories ?? content.stories ?? [];
    res.json({ ...content, _status: specStatus, readinessPercent: computeReadiness(stories) });
  } catch (error: any) {
    handleRouteError(res, error, '[Specs] Get');
  }
});

